 {page==='Vendas'&&<section className="panel"><div className="panel-heading"><div><h2>Vendas registradas</h2><p>Vendas confirmadas e orçamentos criados pela loja.</p></div></div>{s.sales.filter(x=>matches(x.customer,String(x.number))&&(filter==='Todos'||x.status===filter)).length?salesList(s.sales.filter(x=>matches(x.customer,String(x.number))&&(filter==='Todos'||x.status===filter))):<Empty icon={ShoppingBag} title="Nenhuma venda encontrada" text="Crie sua primeira venda ou ajuste a busca."/>}</section>}
 {page==='Estoque'&&<><div className="section-summary"><span><strong>{s.products.length}</strong> produtos · <strong>{low.length}</strong> variações com estoque baixo</span><button className="text-button" onClick={()=>open('movements')}><ClipboardList size={17}/> Histórico de movimentações</button></div><div className="product-grid">{s.products.filter(p=>matches(p.name,p.code,p.category)&&(filter==='Todos'||p.variants.some(v=>v.stock<=p.minimum))).map(p=>{const image=photoUrl(p.photo);return <button className="product-card" key={p.id} onClick={()=>open('product-detail',p)}><div className="product-visual">{image?<img src={image} alt={p.name} onError={e=>{e.currentTarget.style.display='none'}}/>:<Shirt size={45} strokeWidth={1}/>}<span className="product-category">{p.category||'Peça'}</span></div><div className="product-body"><small>{p.code}</small><h3>{p.name}</h3><div className="price-pair"><span>Varejo<strong>{money(p.retail)}</strong></span><span>Atacado<strong>{money(p.wholesale)}</strong></span></div><div className="product-bottom"><span>{plural(p.variants.reduce((n,v)=>n+v.stock,0),'peça','peças')} · {plural(p.variants.length,'variação','variações')}</span><span className="product-badges">{p.catalogVisible===false&&<Badge>Fora do catálogo</Badge>}{p.variants.some(v=>v.stock<=p.minimum)&&<Badge tone="amber">Repor</Badge>}</span></div></div></button>})}</div>{!s.products.filter(p=>matches(p.name,p.code,p.category)&&(filter==='Todos'||p.variants.some(v=>v.stock<=p.minimum))).length&&<section className="panel"><Empty icon={Shirt} title="Vamos colocar suas peças por aqui?" text="Cadastre o produto uma vez e controle cada cor e tamanho." action={<button className="primary" onClick={()=>open('product')}><Plus size={17}/> Cadastrar produto</button>}/></section>}</>}
 {page==='Clientes'&&<section className="panel">{s.customers.filter(c=>matches(c.name,c.phone,c.city)&&(filter==='Todos'||c.type===filter||(filter==='Acompanhar'&&c.followup&&c.followup<=today()))).map(c=>{const sales=confirmed.filter(x=>x.customerId===c.id);return <button className="customer-row" key={c.id} onClick={()=>open('customer-detail',c)}><span className="customer-avatar">{c.name.slice(0,2).toUpperCase()}</span><span className="row-main"><strong>{c.name}</strong><small>{c.phone||'Sem telefone'}{c.city?' · '+c.city:''}</small></span><Badge tone={c.type==='Atacado'?'blue':'neutral'}>{c.type}</Badge><span className="customer-total"><strong>{money(sales.reduce((n,x)=>n+x.total,0))}</strong><small>{plural(sales.length,'compra','compras')}</small></span><ChevronRight size={17}/></button>})}{!s.customers.filter(c=>matches(c.name,c.phone,c.city)&&(filter==='Todos'||c.type===filter||(filter==='Acompanhar'&&c.followup&&c.followup<=today()))).length&&<Empty icon={Users} title="Cada cliente tem uma história" text="Comece pelo nome e contato. As compras completam o histórico." action={<button className="primary" onClick={()=>open('customer')}><Plus size={17}/> Cadastrar cliente</button>}/>}</section>}
