   {printBlocked&&<div className="error" role="alert"><AlertCircle size={18}/>O navegador bloqueou a janela do PDF. Permita pop-ups para este site e clique de novo em Salvar em PDF.</div>}<Field label="Mês do relatório"><input className="month-input" type="month" value={reportMonth} onChange={event=>setReportMonth(event.target.value)} max={today().slice(0,7)}/></Field>
