function authMessage(message:string){if(message==='Invalid login credentials')return 'E-mail ou senha incorretos.';if(/email not confirmed/i.test(message))return 'Confirme seu e-mail pelo link que enviamos antes de entrar.';if(/already registered|already exists/i.test(message))return 'Este e-mail já tem acesso. Use “Já tenho uma conta” para entrar.';if(/password should be at least/i.test(message))return 'A senha precisa ter pelo menos 6 caracteres.';if(/rate limit|security purposes|too many/i.test(message))return 'Muitas tentativas seguidas. Aguarde alguns minutos e tente de novo.';if(/invalid.*email|unable to validate email/i.test(message))return 'Informe um e-mail válido.';return message}
function AuthScreen(){
 const[mode,setMode]=useState<'login'|'signup'>('login'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');setMessage('');const values=Object.fromEntries(new FormData(e.currentTarget)),email=String(values.email||'').trim(),password=String(values.password||'');try{const result=mode==='login'?await supabase.auth.signInWithPassword({email,password}):await supabase.auth.signUp({email,password});if(result.error)setError(authMessage(result.error.message));else if(mode==='signup'&&!result.data.session)setMessage('Confira seu e-mail para confirmar o acesso.')}catch{setError('Não foi possível conectar. Verifique a internet e tente novamente.')}finally{setBusy(false)}}
 return <div className="auth-shell"><section className="auth-card"><div className="auth-logo"><span className="brand-mark">t</span><span>trama<span className="brand-dot">.</span></span></div><div className="eyebrow">SUA LOJA, SEM COMPLICAÇÃO</div><h1>{mode==='login'?'Entre na sua loja':'Crie seu acesso'}</h1><p>{mode==='login'?'Seus produtos, clientes e financeiro ficam salvos com segurança.':'Use um e-mail válido. Enviaremos a confirmação do cadastro.'}</p>{error&&<div className="error" role="alert"><AlertCircle size={17}/>{error}</div>}{message&&<div className="success" role="status"><Check size={17}/>{message}</div>}<form onSubmit={submit}><Field label="E-mail"><input name="email" type="email" autoComplete="email" required autoFocus placeholder="voce@loja.com.br"/></Field><Field label="Senha"><input name="password" type="password" autoComplete={mode==='login'?'current-password':'new-password'} minLength={6} required placeholder="Mínimo de 6 caracteres"/></Field><button className="primary auth-submit" disabled={busy}>{busy?'Aguarde…':mode==='login'?'Entrar':'Criar acesso'}<ArrowRight size={17}/></button></form><button className="text-button auth-switch" onClick={()=>{setMode(mode==='login'?'signup':'login');setError('');setMessage('')}}>{mode==='login'?'Ainda não tenho acesso':'Já tenho uma conta'}</button><small>Dados protegidos por usuário no Supabase.</small></section><aside className="auth-aside"><span className="pill">FEITO PARA A ROTINA</span><h2>Venda, estoque e financeiro trabalhando juntos.</h2><div><span><Check size={17}/> Fácil de usar no celular</span><span><Check size={17}/> SKU gerado automaticamente</span><span><Check size={17}/> Dados persistentes por loja</span></div></aside></div>
}

