 const [type,setType]=useState(r.type||'Varejo'),[method,setMethod]=useState(r.method||'Pix'),[paid,setPaid]=useState('Receber depois'),[direction,setDirection]=useState('out'),[variant,setVariant]=useState(r.variants?.[0]?.id||''),[customer,setCustomer]=useState(''),[search,setSearch]=useState(''),[selected,setSelected]=useState(''),[items,setItems]=useState<{productId:string;variantId:string;qty:number}[]>([]),[discount,setDiscount]=useState('0'),[parts,setParts]=useState('1'),[status,setStatus]=useState('Confirmada');
 const [colors,setColors]=useState([...new Set(initialVariants.map(v=>v.color))].join(', ')),[sizes,setSizes]=useState([...new Set(initialVariants.map(v=>v.size))].join(', ')),[variantStocks,setVariantStocks]=useState<Record<string,string>>(()=>Object.fromEntries(initialVariants.map(v=>[(v.color+'|'+v.size).toLocaleLowerCase(),String(v.stock)])));
