 useEffect(()=>{let active=true;const path=storagePath(photo);if(!path){setPhotoPreview(/^https:\/\//i.test(photo)?photo:'');return()=>{active=false}}void supabase.storage.from('product-images').createSignedUrl(path,3600).then(({data})=>{if(active)setPhotoPreview(data?.signedUrl||'')});return()=>{active=false}},[photo]);
