 const submitButton=(label='Salvar')=><div className="form-actions"><button className="primary" disabled={busy||uploading} type="submit">{uploading?'Enviando foto…':busy?'Salvando…':label}<Check size={17}/></button></div>;
 async function uploadPhoto(file:File){
  setUploadError('');
  if(file.size>10*1024*1024){setUploadError('A imagem deve ter no máximo 10 MB.');return}
  const extensions:Record<string,string>={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif'};
  const extension=extensions[file.type];
  if(!extension){setUploadError('Use uma imagem JPG, PNG, WEBP ou AVIF.');return}
  setUploading(true);
  try{
   const {data:{session}}=await supabase.auth.getSession();
   if(!session?.user)throw new Error('Sua sessão expirou. Entre novamente.');
   const path=`${session.user.id}/${crypto.randomUUID()}.${extension}`;
   const {error}=await supabase.storage.from('product-images').upload(path,file,{contentType:file.type,cacheControl:'31536000',upsert:false});
   if(error)throw error;
   const {data,error:signedError}=await supabase.storage.from('product-images').createSignedUrl(path,3600);
   if(signedError)throw signedError;
   const reference=`${storagePrefix}${path}`;
   const previousPending=storagePath(pendingPhoto);
   if(previousPending)await supabase.storage.from('product-images').remove([previousPending]);
   setPendingPhoto(reference);
   setPhoto(reference);
   setPhotoPreview(data.signedUrl);
  }catch(error){setUploadError(error instanceof Error?error.message:'Não foi possível enviar a imagem. Tente novamente.')}finally{setUploading(false)}
 }
 async function removePhoto(){
  setUploadError('');
  if(photo===pendingPhoto){
   const path=storagePath(pendingPhoto);
   if(path){setUploading(true);const {error}=await supabase.storage.from('product-images').remove([path]);setUploading(false);if(error){setUploadError('Não foi possível remover a imagem. Tente novamente.');return}}
   setPendingPhoto('');
  }
  setPhoto('');setPhotoPreview('');
 }
