 if(modal.type==='customer-detail'){const c=s.customers.find(x=>x.id===r.id)!,sales=s.sales.filter(x=>x.customerId===c.id),bought=sales.filter(x=>x.status==='Confirmada');return <><div className="detail-meta"><Badge tone="blue">{c.type}</Badge><span>{c.city||'Cidade não informada'}</span></div><p>{c.phone||'Telefone não cadastrado'}</p><div className="mini-stats"><span>Total comprado<strong>{money(bought.reduce((n,x)=>n+x.total,0))}</strong></span><span>Última compra<strong>{bought[0]?shortDate(bought[0].date):'Ainda não comprou'}</strong></span></div><div className="inset-box"><h3>Próximo contato</h3><p>{c.followup?shortDate(c.followup):'Nenhum lembrete definido'}</p><p className="notes">{c.notes||'Adicione preferências e detalhes do atendimento.'}</p></div><h3>Histórico de pedidos</h3>{sales.map(x=><button className="history-sale" key={x.id} onClick={()=>open('sale-detail',x)}><span>#{x.number} · {shortDate(x.date)} <Badge>{x.status}</Badge></span><strong>{money(x.total)}</strong></button>)}<div className="form-actions spread"><button className="text-button danger-text" onClick={()=>remove({action:'delete-customer',id:c.id,title:`Excluir ${c.name}?`,description:'O cliente será removido. Cadastros ligados a vendas não podem ser excluídos porque fazem parte do histórico.'})}><Trash2 size={16}/> Excluir cliente</button><button className="primary" onClick={()=>open('customer-edit',c)}>Editar contato e lembrete</button></div></>}
